mapper.select:
SELECT DISTINCT b.tenant_id as tenantId,c.tenant_name as tenantName,o.is_operation as isOperation,b.app_ver_code, b.industry_code, b.points, GROUP_CONCAT( IF ( o.operation_type = '2', o.operation_alarm_type_str, null) ) AS parallel_alarm_type_str, GROUP_CONCAT( IF ( o.operation_type = '1', o.operation_alarm_type_str, null) ) AS serial_alarm_type_str, GROUP_CONCAT( o.operation_type ) AS operation_type, GROUP_CONCAT( DISTINCT NULLIF( CASE WHEN o.operation_type = '2' THEN o.operation_node END, '' )) AS parallelOperationNode, GROUP_CONCAT( DISTINCT NULLIF( CASE WHEN o.operation_type = '1' THEN o.operation_node END, '' )) AS operationNode, GROUP_CONCAT( DISTINCT NULLIF( CASE WHEN o.operation_type = '2' THEN o.operation_dept END, '' )) AS parallelOperationDept, GROUP_CONCAT( DISTINCT NULLIF( CASE WHEN o.operation_type = '1' THEN o.operation_dept END, '' )) AS operationDept, GROUP_CONCAT(o.alarm_source) AS operation_alarm_source, b.oil_gas_pipelines AS pipelines FROM sys_tenant_info c LEFT JOIN vm_algorithm_config b on b.tenant_id = c.tenant_id LEFT JOIN sys_tenant_operation_config o ON o.tenant_id = c.tenant_id and b.industry_code = o.industry_code AND o.delete_flag = '0' and (o.alarm_source = #{alarmSource} or o.alarm_source = '-1')
and o.accept_node = #{localNode}
WHERE c.del_flag = '0' and b.delete_flag = '0' AND b.status = '0' AND EXISTS ( SELECT 1 FROM vm_order_devices ord WHERE ord.device_code = b.device_code AND ord.tenant_id = b.tenant_id AND ord.industry_code = b.industry_code AND ord.delete_flag = 0 AND ord.ord_status IN (0, 1, 2) )
AND b.algorithm_code = #{algorithmCode}
AND b.device_code = #{deviceCode}
AND b.task_id = #{taskId}
GROUP BY c.tenant_id,b.industry_code

SELECT DISTINCT p.tenant_id AS tenantId, t.tenant_name AS tenantName, p.industry_code AS industryCode, p.app_ver_code AS appVerCode FROM vm_air_line_t p LEFT JOIN sys_tenant_info t ON t.tenant_id = p.tenant_id
p.delete_flag = '0'
AND p.flight_route_id = #{routeId}

SELECT DISTINCT a.user_id FROM vm_userinfo_t a LEFT JOIN vm_user_role_rel_t rel ON a.user_id = rel.user_id WHERE a.delete_flag = '0' AND a.source = '0' AND ((EXISTS ( SELECT DISTINCT area_code FROM vm_management_area_region_rela_t WHERE delete_flag = '0' AND region_code IN
#{item}
AND area_code = SUBSTR(a.org_id,1,6))) OR (SUBSTR(a.org_id,1,6) IN ( SELECT SUBSTR(b.org_id,1,6) FROM vm_organ_t b WHERE b.org_level = '1' AND b.org_source = '0' AND b.delete_flag = '0' ))) AND rel.role_id = '11'

select DISTINCT su.user_id, su.dept_id, su.user_name, su.user_type, su.nick_name, su.email, su.avatar, su.phonenumber, su.sex, su.status, su.del_flag, su.login_ip, su.login_date, su.remark, su.login_fail_num, su.enterprise_id, su.tenant_id, su.is_tenant_admin from sys_user su inner join sys_user_role sur on sur.user_id = su.USER_ID
su.DEL_FLAG = '0' and su.STATUS = '0'
AND su.tenant_id = #{tenantId}
AND sur.role_id in
#{item}

select DISTINCT su.user_id, su.dept_id, su.user_name, su.user_type, su.nick_name, su.email, su.avatar, su.phonenumber, su.sex, su.status, su.del_flag, su.login_ip, su.login_date, su.remark, su.login_fail_num, su.enterprise_id, su.tenant_id, su.is_tenant_admin from sys_user su inner join sys_user_role sur on sur.user_id = su.USER_ID
su.DEL_FLAG = '0' and su.STATUS = '0'
AND su.tenant_id = #{tenantId}
AND sur.role_id in
#{item}

SELECT DISTINCT su.user_id, su.dept_id, su.user_name, su.user_type, su.nick_name, su.email, su.avatar, su.phonenumber, su.sex, su.STATUS, su.del_flag, su.login_ip, su.login_date, su.remark, su.login_fail_num, su.enterprise_id, su.tenant_id, su.is_tenant_admin FROM sys_user su INNER JOIN sys_user_role sur ON sur.user_id = su.USER_ID LEFT JOIN ( WITH RECURSIVE cte AS ( SELECT 1 AS n UNION ALL SELECT n + 1 FROM cte WHERE n < 50 ) SELECT su2.user_id, SUBSTRING_INDEX(SUBSTRING_INDEX(su2.DEPT_ID, ',', cte.n), ',', -1) AS dept_id FROM sys_user su2 JOIN cte ON cte.n <= (LENGTH(su2.DEPT_ID) - LENGTH(REPLACE(su2.DEPT_ID, ',', '')) + 1) WHERE su2.DEL_FLAG = '0' AND su2.STATUS = '0' ) ud ON su.user_id = ud.user_id LEFT JOIN sys_dept de ON ud.dept_id = de.DEPT_ID
su.DEL_FLAG = '0' and su.STATUS = '0' and de.INDUSTRY_CODE = #{industryCode}
AND su.tenant_id = #{tenantId}
AND sur.role_id in
#{item}

select DISTINCT su.user_id, su.dept_id, su.user_name, su.user_type, su.nick_name, su.email, su.avatar, su.phonenumber,su.telephone as telPhone, su.sex, su.status, su.del_flag, su.login_ip, su.login_date, su.create_by, su.remark, su.login_fail_num, su.enterprise_id, su.tenant_id, su.is_tenant_admin, sd.dept_name from sys_user su left join sys_dept sd on su.dept_id = sd.dept_id WHERE su.del_flag = '0' and su.STATUS = '0'
AND su.user_id in
#{item}

SELECT su.user_id, sd.dept_id, su.user_name, su.user_type, su.nick_name, su.email, su.avatar, su.phonenumber, su.telephone AS telPhone, su.sex, su.STATUS, su.del_flag, su.login_ip, su.login_date, su.create_by, su.remark, su.login_fail_num, su.enterprise_id, su.tenant_id, su.is_tenant_admin, sd.dept_name FROM sys_user su LEFT JOIN ( WITH RECURSIVE cte AS ( SELECT 1 AS n UNION ALL SELECT n + 1 FROM cte WHERE n < 50 ) SELECT su2.user_id, SUBSTRING_INDEX(SUBSTRING_INDEX(su2.dept_id, ',', cte.n), ',', -1) AS dept_id FROM sys_user su2 JOIN cte ON cte.n <= (LENGTH(su2.dept_id) - LENGTH(REPLACE(su2.dept_id, ',', '')) + 1) ) ud ON su.user_id = ud.user_id LEFT JOIN sys_dept sd ON ud.dept_id = sd.dept_id
and sd.industry_code = #{industryCode}
AND su.user_id in
#{item}

select b.device_code as deviceCode,b.device_name as deviceName,b.channel_code as channelCode,b.channel_name as channelName,b.tenant_id as tenantId
from vm_tenant_device_channel_rel_t b
where b.delete_flag = '0'

    AND b.device_code = #{deviceCode}


    AND b.tenant_id = #{tenantId}


    AND b.channel_code = #{channelCode}



    AND b.device_code in

        #{item}



    AND b.channel_code in

        #{item}

SELECT a.DEVICE_CODE AS deviceCode,a.DEVICE_NAME AS deviceName FROM vm_tenant_device_channel_rel_t a
WHERE a.TENANT_ID = #{tenantId}
AND a.DEVICE_CODE

    #{item.deviceCode}

SELECT a.CHANNEL_CODE as channelCode,a.CHANNEL_NAME as channelName FROM vm_tenant_device_channel_rel_t  a
WHERE a.TENANT_ID = #{tenantId}
AND a.CHANNEL_CODE

    #{item.channelCode}

select

        d.location,d.model_code,d.longitude,d.latitude,d.height,d.model_code,

    c.device_code, c.channel_code
from vm_order_devices c

    left join vm_device_labels_rel dlr on dlr.tenant_id = c.tenant_id and dlr.device_code = c.device_code
    left join vm_tenant_label_config tlc on tlc.label_id = dlr.label_id


    left join vm_organ_device_rel_t odr on odr.tenant_id = c.tenant_id and odr.device_code = c.device_code and odr.delete_flag = '0'


    left join vm_device_info_t d on c.device_code = d.device_code

where c.tenant_id = #{param.tenantId}

    and tlc.label_id = #{param.deviceLabelId,jdbcType=CHAR}


    and tlc.label_id in

        #{item}



    and odr.dept_id = #{param.orgId,jdbcType=CHAR}


    and odr.dept_id in

        #{item}



    and d.model_code = #{param.modelId,jdbcType=CHAR}


    and d.model_code in

        #{item}




    and (c.device_name like CONCAT('%', #{param.deviceName}, '%')
             or d.device_name like CONCAT('%', #{param.deviceName}, '%')
             or c.device_code like CONCAT('%', #{param.deviceName}, '%')
             or d.device_code like CONCAT('%', #{param.deviceName}, '%'))

select distinct d.device_code, d.latitude, d.longitude, d.height, d.model_code as modelId,data.DICT_LABEL as modelName from vm_order_devices dataTable left join vm_device_info_t d on dataTable.device_code = d.device_code left join sys_dict_data data on d.model_code = data.DICT_VALUE where dataTable.delete_flag = '0' and d.delete_flag = '0' and data.DICT_TYPE = '103'
and d.model_code = #{modelId}
and d.device_code in
#{item}
${dataScope}

SELECT DISTINCT b.tenant_id as tenantId,b.tenant_name as tenantName,o.is_operation as isOperation,od.app_ver_code, c.industry_code, GROUP_CONCAT( IF ( o.operation_type = '2', o.operation_alarm_type_str, null) ) AS parallel_alarm_type_str, GROUP_CONCAT( IF ( o.operation_type = '1', o.operation_alarm_type_str, null) ) AS serial_alarm_type_str, GROUP_CONCAT( o.operation_type ) AS operation_type, GROUP_CONCAT( DISTINCT NULLIF( CASE WHEN o.operation_type = '2' THEN o.operation_node END, '' )) AS parallelOperationNode, GROUP_CONCAT( DISTINCT NULLIF( CASE WHEN o.operation_type = '1' THEN o.operation_node END, '' )) AS operationNode, GROUP_CONCAT( DISTINCT NULLIF( CASE WHEN o.operation_type = '2' THEN o.operation_dept END, '' )) AS parallelOperationDept, GROUP_CONCAT( DISTINCT NULLIF( CASE WHEN o.operation_type = '1' THEN o.operation_dept END, '' )) AS operationDept, GROUP_CONCAT(o.alarm_source) AS operation_alarm_source FROM sys_tenant_info b LEFT JOIN vm_order_sensor_devices od on od.tenant_id = b.tenant_id LEFT JOIN sys_tenant_operation_config o ON o.tenant_id = b.tenant_id AND o.delete_flag = '0' AND (o.alarm_source = #{alarmSource} or o.alarm_source = '-1')
and o.accept_node = #{localNode}
LEFT JOIN vm_radar_alarm_template c ON c.tenant_id = b.tenant_id
where od.delete_flag = '0'
and od.app_ver_code = #{applicationCode}
and c.task_id = #{taskId} and c.delete_flag ='0' and c.template_status = '1'
and od.device_code in
#{item}
and od.ord_status in(0, 1, 2) and od.category_code = #{categoryCode} GROUP BY b.tenant_id,od.industry_code

SELECT DISTINCT b.tenant_id as tenantId,b.tenant_name as tenantName,b.is_operation as isOperation,od.app_ver_code, od.industry_code, od.device_code,b.operation_alarm_type_str as operationAlarmTypeStr FROM sys_tenant_info b,vm_order_sensor_devices od where od.device_code IN
#{item}
and od.tenant_id = b.tenant_id and od.delete_flag = '0' and od.ord_status in(0, 1, 2) and od.category_code = 2

SELECT pan,hor_offset as horOffset,pitch_offset as pitchOffset,device_code as deviceCode FROM vm_device_ref_point_valid_t where device_code in
#{item}
and point_flag = '1' group by device_code

select device_code, event_no warning_order_id, address formatted_address,longitude,latitude,
       event_pan ptz_p,event_tilt ptz_t,pan_max p_max,pan_min p_min,tilt_max t_max,tilt_min t_min,real_hor_angle hori_azimuth_angle,creator creator,creator_date create_time
        ,status,modifier modifier,modifier_date update_time,id
from vm_device_feature_lib
where status = '1'
AND device_code = #{deviceCode}
AND pan_max >= #{ptzP}
AND pan_min <= #{ptzP}
AND tilt_max >= #{ptzT}
AND tilt_min <= #{ptzT}
order by creator_date

SELECT
    t.coll_obj_code AS collObjCode
FROM
    vm_user_device_collection_t t
WHERE
    t.user_id = #{userId}
    AND t.coll_obj_type = #{collObjType}
    AND t.coll_obj_code in

        #{code}

SELECT a.latitude, a.longitude, a.location, a.province_id, a.city_id, a.county_id, a.height, a.model_code AS modelId, a.device_code, a.device_name, a.device_model_code AS deviceModelCode, p.area_name AS provinceName, ci.area_name AS cityName, co.area_name AS countyName FROM vm_iot_device_t a left join vm_iot_device_model_t t on a.device_model_code = t.device_model_code and a.model_code = t.mfgr_code LEFT JOIN sys_area p ON a.province_id = p.area_code LEFT JOIN sys_area ci ON a.city_id = ci.area_code LEFT JOIN sys_area co ON a.county_id = co.area_code WHERE a.delete_flag = '0'
and a.device_code = #{deviceCode}
LIMIT 1

SELECT osd.tenant_id, a.device_code, IFNULL(b.device_name,a.device_name) as deviceName, a.latitude, a.longitude, a.location, a.province_id, a.city_id, a.county_id, a.height, a.model_code AS modelId, a.device_model_code AS deviceModelCode, p.area_name AS provinceName, ci.area_name AS cityName, co.area_name AS countyName from vm_order_sensor_devices osd left join vm_iot_device_t a on a.device_code = osd.device_code left join vm_tenant_iot_device_rel_t b on b.device_code = osd.device_code and osd.tenant_id = b.tenant_id LEFT JOIN sys_area p ON a.province_id = p.area_code LEFT JOIN sys_area ci ON a.city_id = ci.area_code LEFT JOIN sys_area co ON a.county_id = co.area_code WHERE a.delete_flag = '0' and osd.category_code = 1 and osd.ord_status in (0,1,2) and osd.tenant_id = #{tenantId} and osd.industry_code = #{industryCode}
and a.device_code = #{deviceCode}
LIMIT 1

SELECT a.latitude, a.longitude, a.location, a.province_id, a.city_id, a.county_id, a.height, a.model_code AS modelId, a.device_code, a.device_name, a.device_model_code AS deviceModelCode, p.area_name AS provinceName, ci.area_name AS cityName, co.area_name AS countyName FROM vm_iot_device_t a LEFT JOIN sys_area p ON a.province_id = p.area_code LEFT JOIN sys_area ci ON a.city_id = ci.area_code LEFT JOIN sys_area co ON a.county_id = co.area_code WHERE a.delete_flag = '0' AND a.category_code = #{categoryCode}
and a.device_code = #{deviceCode}
LIMIT 1

SELECT preset_name
FROM vm_algorithm_config
where delete_flag = 0 and task_id = #{taskId}

SELECT reg.tenant_id AS tenantId, callback_url AS callbackUrl FROM sys_auth_register_api reg LEFT JOIN sys_auth_register_func_api func ON reg.id = func.register_id WHERE reg.delete_flag = '1' AND reg.is_open = '1' AND reg.tenant_id in
#{item}
AND func.delete_flag = '1' AND func.api_intf_code = '910'
